class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def imgMultiply(root):
    MOD = 10**9 + 7

    def dfs(node1, node2):
        if not node1 and not node2:
            return 0
        if not node1 or not node2:
            return 0
        current_product = (node1.val * node2.val) % MOD
        left_sum = dfs(node1.left, node2.right)
        right_sum = dfs(node1.right, node2.left)
        return (current_product + left_sum + right_sum) % MOD

    return dfs(root, root)

# Example usage:
# root = TreeNode(4, TreeNode(5), TreeNode(6))
# print(imgMultiply(root))  # Output: 46
